style.css:
/* Apply lavender swirl background */
body {
  position: relative;
  min-height: 100vh;
  margin: 0;
  background: none;
  overflow-x: hidden;
  color: #6a0dad; /* default purple text color */
}

/* Soft lavender gradient base */
body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -2;

  background: radial-gradient(circle at 20% 30%, #e6e6fa 0%, #f3e5f5 40%, #e6e6fa 100%);
  background-size: 200% 200%;
  animation: lavenderShift 25s ease infinite;
}

/* Swirls effect */
body::after {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 200%;
  height: 200%;
  z-index: -1;
  pointer-events: none;

  background-image: repeating-radial-gradient(
      circle at 20% 20%,
      rgba(255, 255, 255, 0.2) 0,
      transparent 80px
    ),
    repeating-radial-gradient(
      circle at 80% 80%,
      rgba(255, 255, 255, 0.15) 0,
      transparent 100px
    ),
    repeating-radial-gradient(
      circle at 50% 50%,
      rgba(255, 255, 255, 0.1) 0,
      transparent 120px
    );
  background-size: 400px 400px, 600px 600px, 800px 800px;
  animation: swirlFloat 80s linear infinite;
}

/* Animate gradient shift */
@keyframes lavenderShift {
  0%   { background-position: 0% 50%; }
  50%  { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

/* Animate swirls slowly */
@keyframes swirlFloat {
  0%   { transform: rotate(0deg) translate(0,0); }
  50%  { transform: rotate(20deg) translate(-50px,-50px); }
  100% { transform: rotate(0deg) translate(0,0); }
}

/* Ensure all plain black text turns purple */
body, body * {
  color: #6a0dad !important;
}
